contract InvMutTest {
  C c;
  constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

  function test(uint256 amt) public {
    require(c.owner() == address(this));
    c.mintToken(address(this), amt); if (__ESBMC_reverted()) return;
    assert(!c.frozenAccount(address(this)));
  }
}

